[asy]
unitsize(0.5 cm);

pair C, P, Q;

C = (-1,4);
P = (0,2);
Q = (-3,8);
draw((-5,0)--(5,0));
draw((0,-1)--(0,10));
draw(P--Q,dashed);

dot("$-1 + 4i$", C, SW);
dot("$2i$", P, E);
dot("$-3 + 8i$", Q, NW);
[/asy]

